.border-t{border-top-width: 1px;}
.border-stark-white\/10{border-color: rgba(255, 255, 255, 0.1);}
.bg-denim-black{--tw-bg-opacity: 1; background-color: rgb(8 8 8 / var(--tw-bg-opacity, 1));}
.bg-stark-white{--tw-bg-opacity: 1; background-color: rgb(255 255 255 / var(--tw-bg-opacity, 1));}
.px-8{padding-left: 2rem; padding-right: 2rem;}
.py-32{padding-top: 8rem; padding-bottom: 8rem;}
.pt-8{padding-top: 2rem;}
.text-\[15vw\]{font-size: 15vw;}
.leading-\[0\.75\]{line-height: 0.75;}
.text-stark-white{--tw-text-opacity: 1; color: rgb(255 255 255 / var(--tw-text-opacity, 1));}
.opacity-20{opacity: 0.2;}
.transition-opacity{transition-property: opacity; transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1); transition-duration: 150ms;}
.duration-1000{transition-duration: 1000ms;}
.hover\:text-silver-lens:hover{--tw-text-opacity: 1; color: rgb(192 192 192 / var(--tw-text-opacity, 1));}
.hover\:opacity-100:hover{opacity: 1;}
@media (min-width: 1024px){.lg\:col-span-5{grid-column: span 5 / span 5;}}
@media (min-width: 1024px){.lg\:col-span-7{grid-column: span 7 / span 7;}}
